import {cardSVG} from './artwork.js';
import {cards,DECK_SIZE,STORAGE_KEY,blank,restore,acquire,points,match,parseCode,remember,sharedReading} from './model.js';
const $=s=>document.querySelector(s), main=$('#main'), modal=$('#modal');
let state=blank(),storage=true;
try {state=restore(JSON.parse(localStorage.getItem(STORAGE_KEY)));}catch{storage=false;}
let disposeScene=()=>{},disposeGesture=()=>{},drawTimer;
let pairFirst='chicken-rice',pairSecond='kaya-toast';
let screen='home',answers=[],question=0,stage='ready',timer,stream,scanTimer,kind='place',previewTheme='All',collectionTheme='All',selectedPreviewId=cards[0].id;
function save(){try{localStorage.setItem(STORAGE_KEY,JSON.stringify(state));}catch{storage=false;toast('Browser storage unavailable. Keep this tab open to preserve progress.');}update();}
function update(){$('#count').textContent=`${state.owned.length}/${DECK_SIZE}`;$('#points').textContent=points(state);document.querySelectorAll('[data-nav]').forEach(b=>b.classList.toggle('active',b.dataset.nav===screen));}
function toast(text){$('#toast').textContent=text;$('#toast').classList.add('show');clearTimeout(timer);timer=setTimeout(()=>$('#toast').classList.remove('show'),4000);}
function card(c,back=false){return `<div class="playing-card ${back?'back':''}">${cardSVG(c,back)}</div>`;}
function stopCamera(){clearTimeout(scanTimer);stream?.getTracks().forEach(t=>t.stop());stream=null;}
function nav(target){stopCamera();clearTimeout(drawTimer);if(stage==='shuffling')stage='ready';screen=target;render();window.scrollTo({top:0,behavior:'smooth'});}
const themes=['All',...new Set(cards.map(c=>c.theme))];
function themeFilters(selected,kind){return `<div class="theme-filters" role="group" aria-label="Filter cards by theme">${themes.map(theme=>`<button data-${kind}-filter="${theme}" class="${selected===theme?'active':''}" aria-pressed="${selected===theme}">${theme} <span>${theme==='All'?DECK_SIZE:cards.filter(c=>c.theme===theme).length}</span></button>`).join('')}</div>`;}
function visibleCards(theme){return theme==='All'?cards:cards.filter(c=>c.theme===theme);}
function previewCards(){return visibleCards(previewTheme).map(c=>`<button data-preview="${c.id}" class="preview-pick ${selectedPreviewId===c.id?'active':''}" aria-pressed="${selectedPreviewId===c.id}" aria-label="Preview ${c.name}"><span class="preview-number">${String(cards.indexOf(c)+1).padStart(2,'0')} · ${c.theme}</span>${card(c)}<span class="preview-label">${c.word}</span></button>`).join('');}
function selectPreview(id){selectedPreviewId=id;const chosen=cards.find(c=>c.id===id);$('#scene-name').textContent=chosen.name;$('#scene-word').textContent=chosen.word;document.querySelectorAll('[data-preview]').forEach(b=>{b.classList.toggle('active',b.dataset.preview===id);b.setAttribute('aria-pressed',String(b.dataset.preview===id));});const fallback=$('.scene-fallback');if(fallback)fallback.innerHTML=card(cards[(cards.indexOf(chosen)+1)%DECK_SIZE])+card(cards[(cards.indexOf(chosen)+2)%DECK_SIZE])+card(chosen);}
function bindPreview(){main.querySelectorAll('[data-preview]').forEach(b=>b.onclick=()=>{window.LittleRedScene?.select(b.dataset.preview);selectPreview(b.dataset.preview);});}
function home(){return `<section class="hero persona-hero"><div class="hero-copy"><div class="issue-label"><span class="issue-square">✦</span> VOL. 01 / THE EVERYDAY ARCANA</div><h1><span class="headline-small">THE CITY HAS A STORY.</span><span class="headline-main">FIND<br>YOUR<br><em>PLACE.</em></span></h1><p class="intro">A personal reading. A local discovery. A connection waiting to happen. Meet Singapore through 22 cards — and find a little of yourself.</p><div class="actions"><button class="primary" id="begin">${state.personal?'VIEW MY PERSONAL CARD':'DRAW YOUR PERSONAL CARD'} <svg class="icon" viewBox="0 0 20 20" fill="none" stroke="currentColor" stroke-width="2" aria-hidden="true"><path d="M4 16 16 4M5 4h11v11"/></svg></button><button class="secondary" data-go="scan">SCAN & COLLECT <span>⌗</span></button></div><p class="small-note">${state.personal?'Your story has begun. Keep discovering.':'Three questions. 22 possibilities. One card that feels like you.'}</p><div class="coordinates">01°17′ N &nbsp; 103°51′ E <span>SINGAPORE</span></div></div><div class="hero-visual"><div class="scene-grid"></div><div class="scene-orbit orbit-one"></div><div class="scene-orbit orbit-two"></div><div class="scene-caption">22 STORIES / ONE LITTLE RED DOT</div><div id="card-scene" class="card-scene" role="img" aria-label="Interactive 3D fan from the 22-card Singapore tarot collection"><div class="scene-fallback">${card(cards[2])}${card(cards[4])}${card(cards[0])}</div></div><div class="scene-detail"><span id="scene-word">Comfort</span><b id="scene-name">Hainanese chicken rice</b><small id="scene-hint">DRAG TO TURN · TAP A CARD TO EXPLORE</small></div><div class="scene-burst" aria-hidden="true">✳</div></div></section><div class="ticker" aria-hidden="true"><span>FOOD / RITUALS / ARTS / PLACES</span><span>DISCOVER THE EVERYDAY ARCANA ✦</span><span>ONE CITY. MANY CONNECTIONS.</span></div><section class="deck-preview"><div class="section-top"><div><div class="eyebrow">THE NAN YANG COLLECTION</div><h2>Ordinary things.<br><em>Extraordinary meanings.</em></h2></div><p>Inspired by tropical colour, local craft<br>and the rhythms of life in Singapore.</p></div>${themeFilters(previewTheme,'preview')}<div class="preview-strip" aria-label="Explore the 22-card deck">${previewCards()}</div></section><section class="demo-experiences"><div class="eyebrow">A little more connection</div><h2>Three ways to make it yours.</h2><div class="experience-grid"><article><span class="num">01 / TOUCH</span><h3>A story in your hands.</h3><p>Shuffle, cut, draw and turn. Follow the gestures or use simple buttons.</p><button class="secondary" id="try-tactile">Try the tactile reveal →</button></article><article><span class="num">02 / TOGETHER</span><h3>Two cards. One conversation.</h3><p>Bring two personal cards together for a reflection and a moment of listening.</p><button class="secondary" data-go="together">Try a two-person reading →</button></article><article><span class="num">03 / REMEMBER</span><h3>A place for your memory.</h3><p>Keep a personal note beside the chicken-rice story. Only in this browser, only if you want to.</p><button class="secondary" id="try-memory">Open the chicken-rice card →</button></article></div></section><section class="journey"><div class="section-top"><h2>Your next move.</h2><p>Every card opens a new connection.</p></div><div class="steps"><div class="step"><span class="num">01</span><div><h3>MEET YOURSELF</h3><p>Answer three questions. Watch the whole deck shuffle, draw, then flip your personal card.</p></div></div><div class="step"><span class="num">02</span><div><h3>MEET THE CITY</h3><p>Scan a place QR. Read the cultural story. Collect a card inspired by what you discover.</p></div></div><div class="step"><span class="num">03</span><div><h3>MEET YOUR PEOPLE</h3><p>Scan a personal-card QR to receive a copy. Both people keep their cards. Complete all 22 for a bonus.</p></div></div></div></section>`;}
const questions=[{title:'What are you drawn to today?',opts:[['A little comfort','Something simple and nourishing.'],['A fresh beginning','A small change, a new possibility.'],['A good conversation','Time to connect and listen.'],['An unexpected discovery','A different way to see things.']]},{title:'How do you approach a new place?',opts:[['Follow the flavours','Find a table and settle in.'],['Meet the people','Ask, listen, and share.'],['Notice the details','Look closely at what is made.'],['Let curiosity lead','Take the path you haven’t tried.']]},{title:'What would you like to make room for?',opts:[['Steadiness','More care in everyday moments.'],['Connection','A little more giving and receiving.'],['Patience','Time to create something meaningful.'],['Perspective','A story beyond the first impression.']]}];
function questionnaire(){const q=questions[question];return `<section class="flow"><button class="back-link" id="qback">← ${question?'Previous question':'Back to discover'}</button><div class="progress">${questions.map((_,i)=>`<span class="${i<=question?'done':''}"></span>`).join('')}</div><div class="eyebrow">A moment for yourself · ${question+1} of 3</div><h1>${q.title}</h1><p class="small-note">No right answers. Just what feels like you.</p><div class="options" role="group" aria-label="Choose one answer">${q.opts.map((o,i)=>`<button class="option ${answers[question]===i?'selected':''}" aria-pressed="${answers[question]===i}" data-answer="${i}">${o[0]}<span>${o[1]}</span></button>`).join('')}</div><button class="primary" id="next" ${answers[question]===undefined?'disabled':''}>${question===2?'Meet the deck':'Continue'} →</button><p class="small-note">Answers shape a creative reflection; this is not a prediction.</p></section>`;}
function draw(){const c=cards.find(c=>c.id===(state.personal||match(answers)));if(stage==='revealed')return `<section class="flow"><div class="eyebrow">Your personal card</div><h1>${c.word}, in your own way.</h1>${card(c)}<p class="reading">${c.reading}</p><p class="small-note">A creative reflection inspired by your answers.</p><div class="actions"><button class="primary" data-go="collection">Explore my deck →</button><button class="secondary" id="share">Share my card</button><button class="secondary" data-go="together">Read together</button>${c.id==='chicken-rice'?'<button class="secondary" id="try-memory">Add an optional memory</button>':''}</div></section>`;
const labels={ready:['Let the possibilities unfold.','Drag sideways across the deck to shuffle.','Shuffle the whole deck'],shuffling:['A little chance. A little you.','All 22 cards are finding their place.','Shuffling…'],shuffled:['Make a little space.','Drag sideways to cut the deck into two piles.','Cut the deck'],cut:['Your card is waiting.','Drag upward to draw your card.','Draw a card'],drawn:['Turn a new page.','Drag sideways to turn your card and reveal its story.','Flip my card']},[title,hint,action]=labels[stage];
return `<section class="flow tactile-flow"><div class="eyebrow">A small ritual of discovery</div><h1>${title}</h1><p id="gesture-hint" class="small-note" aria-live="polite">${hint}</p><div id="tactile-deck" class="deck-stage tactile-deck ${stage==='shuffling'?'shuffling':''} ${stage==='cut'?'cut-deck':''}" aria-label="${hint}" aria-describedby="gesture-hint">${stage==='drawn'?`<button class="drawn" id="flip" aria-label="Flip your personal card">${card(c,true)}</button>`:cards.map((c,i)=>`<div style="--i:${i/(DECK_SIZE-1)*5};--pile:${i<DECK_SIZE/2?-1:1}">${card(c,true)}</div>`).join('')}</div><div class="actions"><button class="primary" id="draw-action" ${stage==='shuffling'?'disabled':''}>${action} <span>✦</span></button><button class="secondary" id="simple-reveal">Simple reveal</button></div><p class="small-note">Every gesture has a button. Simple reveal skips straight to your reading.${state.personal?' Your existing personal card stays yours.':''}</p></section>`;}
function together(){const result=sharedReading(pairFirst,pairSecond);return `<section class="together-flow"><button class="back-link" data-go="home">← Back to discover</button><div class="eyebrow">A shared reflection</div><h1>Two cards.<br>Room for both.</h1><p class="intro">Take turns speaking and listening. You can pass on any question.</p><p class="small-note">Try any two cards here, or scan a person’s QR and choose “Read together”. This demo does not collect or change either personal card.</p><div class="pair-selectors"><div><label for="pair-first">Person one’s card${state.personal===pairFirst?' · your personal card':''}</label><select id="pair-first">${cards.map(c=>`<option value="${c.id}" ${pairFirst===c.id?'selected':''}>${c.name}</option>`).join('')}</select></div><div><label for="pair-second">Person two’s card</label><select id="pair-second">${cards.map(c=>`<option value="${c.id}" ${pairSecond===c.id?'selected':''}>${c.name}</option>`).join('')}</select></div></div><button class="primary" id="read-pair">Bring our cards together ✦</button><div id="pair-result" class="pair-result" aria-live="polite"><div class="paired-cards">${card(cards.find(c=>c.id===pairFirst))}<span aria-hidden="true">✦</span>${card(cards.find(c=>c.id===pairSecond))}</div><div class="pair-copy"><span class="badge">A conversation, at your pace</span><h2>${result.title}</h2><p>${result.reflection}</p><ol>${result.prompts.map(prompt=>`<li>${prompt}</li>`).join('')}</ol><p class="small-note">An original creative reflection. No compatibility score or prediction. Both people keep their cards.</p></div></div></section>`;}
function drawAdvance(){if(stage==='ready'){stage='shuffling';render();drawTimer=setTimeout(()=>{if(screen==='draw'&&stage==='shuffling'){stage='shuffled';render();}},window.matchMedia?.('(prefers-reduced-motion: reduce)').matches?150:3100);}else if(stage==='shuffled'){stage='cut';render();}else if(stage==='cut'){stage='drawn';render();}else if(stage==='drawn')reveal();}
function bindTactile(){const el=$('#tactile-deck');if(!el||stage==='shuffling')return;let pointer=null,startX=0,startY=0,dx=0,dy=0;
const reset=()=>{pointer=null;el.classList.remove('is-dragging');el.style.removeProperty('--drag-x');el.style.removeProperty('--drag-y');el.style.removeProperty('--turn');};
el.onpointerdown=e=>{if(!e.isPrimary||e.button!==0)return;pointer=e.pointerId;startX=e.clientX;startY=e.clientY;dx=dy=0;el.setPointerCapture(e.pointerId);el.classList.add('is-dragging');};
el.onpointermove=e=>{if(e.pointerId!==pointer)return;dx=e.clientX-startX;dy=e.clientY-startY;el.style.setProperty('--drag-x',`${Math.max(-75,Math.min(75,dx))}px`);el.style.setProperty('--drag-y',`${Math.max(-100,Math.min(30,dy))}px`);el.style.setProperty('--turn',`${Math.max(-75,Math.min(75,dx))}deg`);};
el.onpointerup=e=>{if(e.pointerId!==pointer)return;const completed=stage==='cut'?dy<-45:Math.abs(dx)>45||(stage==='drawn'&&Math.hypot(dx,dy)<8);reset();if(completed){el.addEventListener('click',e=>{e.preventDefault();e.stopPropagation();},{capture:true,once:true});drawAdvance();}};
el.onpointercancel=reset;el.onlostpointercapture=reset;disposeGesture=reset;
}
function collection(){return `<section><div class="collection-header"><div><div class="eyebrow">Your little discoveries</div><h1>Stories worth keeping.</h1><p class="intro">${state.owned.length} of ${DECK_SIZE} cards collected. Every new card adds 10 points.</p></div><button class="primary" data-go="scan">Scan & collect ↗</button></div><div class="meter" role="progressbar" aria-label="Collection progress" aria-valuemin="0" aria-valuemax="${DECK_SIZE}" aria-valuenow="${state.owned.length}"><span style="width:${state.owned.length/DECK_SIZE*100}%"></span></div><p class="small-note">${state.bonus?'All 22 stories, one complete deck.':'Complete all 22 for a 50-point bonus.'} · Points are for this prototype.</p>${state.legacyBonus?'<p class="small-note">Your previously earned 50-point starter-deck bonus is included in your total.</p>':''}${state.bonus?'<div class="banner">✦ The whole little deck! You earned the 50-point completion bonus.</div>':''}${!state.personal?'<button class="secondary" id="begin">Find my personal card →</button>':''}<div id="collection-filters">${themeFilters(collectionTheme,'collection')}</div><div class="grid">${visibleCards(collectionTheme).map(c=>`<button class="collection-item ${state.owned.includes(c.id)?'':'locked'}" data-card="${c.id}" aria-label="${c.name}${state.owned.includes(c.id)?', collected':', not collected'}">${card(c)}<p>${state.personal===c.id?'✦ Your personal card':state.owned.includes(c.id)?'✓ Collected':'+ Waiting to be discovered'}</p></button>`).join('')}</div></section>`;}
function scan(){return `<section><div class="eyebrow">Places & people</div><h1>Find your next story.</h1><p class="intro">A place holds a story. A person holds a connection.<br>Scan a QR to add one to your deck.</p><div class="scan-layout"><div><div class="scanner" id="scanner"><span class="scanner-symbol">⌗</span><p>Point your camera at a card QR</p><button class="primary" id="camera">Open camera</button></div><p class="small-note">Camera scanning depends on browser support. You can also paste a card link or use a demo below.</p><label for="code">Card link or code</label><input id="code" placeholder="e.g. place:kaya-toast" autocomplete="off"><div id="scan-error" class="error" role="alert"></div><button class="secondary" id="code-go">Open card →</button></div><div><span class="badge">TRY THE PROTOTYPE</span><h2>Take a little detour.</h2><p class="small-note">These demo codes stand in for physical signs and another person’s card. No venue partnerships are implied.</p><div class="tabs" role="group" aria-label="Demo QR type"><button data-kind="place" class="${kind==='place'?'active':''}">Place QR</button><button data-kind="person" class="${kind==='person'?'active':''}">Person’s QR</button></div><div class="demo-list">${cards.map(c=>`<button data-demo="${c.id}">${c.name}<br><span class="small-note">${kind==='place'?c.place:'Receive a personal-card copy'} ↗</span></button>`).join('')}</div></div></div></section>`;}
function render(){disposeGesture();disposeGesture=()=>{};disposeScene();disposeScene=()=>{};document.body.dataset.screen=screen;update();main.innerHTML=screen==='home'?home():screen==='questions'?questionnaire():screen==='draw'?draw():screen==='collection'?collection():screen==='together'?together():scan();
main.querySelectorAll('[data-go]').forEach(b=>b.onclick=()=>{if(b.dataset.go==='together'&&state.personal)pairFirst=state.personal;nav(b.dataset.go);});
const begin=$('#begin');if(begin)begin.onclick=()=>{if(state.personal)showCard(state.personal);else{answers=[];question=0;nav('questions');}};
main.querySelectorAll('[data-answer]').forEach(b=>b.onclick=()=>{answers[question]=Number(b.dataset.answer);render();});
if($('#next'))$('#next').onclick=()=>{if(question<2){question++;render();}else{stage='ready';nav('draw');}};
if($('#qback'))$('#qback').onclick=()=>{if(question){question--;render();}else nav('home');};
if($('#draw-action'))$('#draw-action').onclick=drawAdvance;
if($('#simple-reveal'))$('#simple-reveal').onclick=()=>{clearTimeout(drawTimer);stage='drawn';reveal();};
if($('#flip'))$('#flip').onclick=reveal;
if(screen==='draw')bindTactile();
if($('#try-tactile'))$('#try-tactile').onclick=()=>{if(state.personal){stage='ready';nav('draw');}else{answers=[];question=0;nav('questions');}};
if($('#try-memory'))$('#try-memory').onclick=()=>{if(state.owned.includes('chicken-rice'))showCard('chicken-rice');else openCode('place:chicken-rice');};
if($('#read-pair'))$('#read-pair').onclick=()=>{pairFirst=$('#pair-first').value;pairSecond=$('#pair-second').value;render();$('#pair-result').setAttribute('tabindex','-1');$('#pair-result').focus();};
if($('#share'))$('#share').onclick=share;
main.querySelectorAll('[data-card]').forEach(b=>b.onclick=()=>showCard(b.dataset.card));
main.querySelectorAll('[data-kind]').forEach(b=>b.onclick=()=>{stopCamera();kind=b.dataset.kind;render();});
main.querySelectorAll('[data-demo]').forEach(b=>b.onclick=()=>openCode(`${kind}:${b.dataset.demo}`));
if($('#code-go'))$('#code-go').onclick=()=>openCode($('#code').value);
if($('#code'))$('#code').onkeydown=e=>{if(e.key==='Enter')openCode(e.target.value);};
if($('#camera'))$('#camera').onclick=camera;
if(screen==='home'){
 if(window.LittleRedScene){disposeScene=window.LittleRedScene.mount($('#card-scene'),{onSelect:selectPreview});window.LittleRedScene.select(selectedPreviewId);}
 selectPreview(selectedPreviewId);bindPreview();
 main.querySelectorAll('[data-preview-filter]').forEach(b=>b.onclick=()=>{previewTheme=b.dataset.previewFilter;main.querySelectorAll('[data-preview-filter]').forEach(t=>{t.classList.toggle('active',t===b);t.setAttribute('aria-pressed',String(t===b));});$('.preview-strip').innerHTML=previewCards();bindPreview();});
}
main.querySelectorAll('[data-collection-filter]').forEach(b=>b.onclick=()=>{collectionTheme=b.dataset.collectionFilter;render();});
}
function collect(id){const result=acquire(state,id);state=result.state;save();toast(result.duplicate?'Already in your deck. No extra points.':result.award===60?'New card +10 · Complete deck bonus +50!':'New card collected · +10 points');return result;}
function reveal(){if(stage!=='drawn')return;state.personal=state.personal||match(answers);if(!state.owned.includes(state.personal))collect(state.personal);stage='revealed';render();}
function openModal(html){stopCamera();$('#modal-body').innerHTML=html;if(!modal.open)modal.showModal();}
function memoryForm(){return `<section class="memory-panel"><span class="badge">Your memory · optional</span><h3>What makes this meal yours?</h3><p class="small-note">A table, a person, a small moment. Your note stays in this browser and is never included in card QRs. The cultural story stays as it is.</p><label for="card-memory">Personal memory (up to 600 characters)</label><textarea id="card-memory" maxlength="600" rows="4" placeholder="I remember…"></textarea><div class="actions"><button class="primary" id="save-memory">Save memory</button><button class="secondary" id="delete-memory">Delete memory</button><button class="back-link" id="skip-memory">Skip / close</button></div><p id="memory-status" class="small-note" role="status"></p></section>`;}
function bindMemory(){if(!$('#card-memory'))return;$('#card-memory').value=state.memories['chicken-rice']||'';$('#save-memory').onclick=()=>{state=remember(state,$('#card-memory').value);save();$('#memory-status').textContent=storage?'Memory saved only in this browser.':'Storage unavailable. Memory is kept only while this tab stays open.';};$('#delete-memory').onclick=()=>{state=remember(state,'');save();$('#card-memory').value='';$('#memory-status').textContent='Memory deleted.';};$('#skip-memory').onclick=()=>modal.close();}
function showCard(id){const c=cards.find(c=>c.id===id);openModal(`<div class="eyebrow">${state.personal===id?'Your personal card':c.theme}</div><h2>${c.name}</h2>${card(c)}${c.draftStory?'<span class="badge">Draft cultural note</span>':''}<p>${c.story}</p><a class="source" href="${c.source}" target="_blank" rel="noopener">Source & context ↗</a><p>${state.owned.includes(id)?c.reading:'Discover this card through a place or person’s QR.'}</p>${state.personal===id?'<button class="primary" id="share-modal">Share my card ↗</button>':''}${id==='chicken-rice'&&state.owned.includes(id)?memoryForm():''}`);if($('#share-modal'))$('#share-modal').onclick=share;bindMemory();}
function openCode(code){try{const {kind,id}=parseCode(code),c=cards.find(c=>c.id===id),owned=state.owned.includes(id);openModal(`<div class="eyebrow">${kind==='place'?'A place, a story':'A connection worth keeping'}</div><h2>${c.name}</h2>${card(c)}${kind==='person'?'<p>You’ll receive a copy of this person’s personal card. Their card stays with them, and yours stays with you.</p>':''}${c.draftStory?'<span class="badge">Draft cultural note</span>':''}<p>${c.story}</p><a class="source" href="${c.source}" target="_blank" rel="noopener">Source & context ↗</a><div class="actions"><button class="primary" id="collect">${owned?'Already collected':'Collect card'} ${owned?'✓':'+10'}</button>${kind==='person'&&state.personal?'<button class="secondary" id="pair-scanned">Read together</button>':''}</div><p class="small-note">${owned?'Duplicate cards earn no extra points.':kind==='person'?'Only the card type is shared, not their answers or reading history.':'Add this story to your 22-card deck.'}</p>`);$('#collect').onclick=()=>{collect(id);modal.close();nav('collection');if(id==='chicken-rice')showCard(id);};if($('#pair-scanned'))$('#pair-scanned').onclick=()=>{pairFirst=state.personal;pairSecond=id;modal.close();nav('together');};}catch(e){if($('#scan-error'))$('#scan-error').textContent=e.message;else toast(e.message);}}
function share(){if(!state.personal)return;const code=`person:${state.personal}`,url=new URL(location.href);url.hash=new URLSearchParams({card:code}).toString();const qr=qrcode(0,'M');qr.addData(url.href);qr.make();openModal(`<div class="eyebrow">Pass on a little connection</div><h2>Your card is yours to keep.</h2><p>Let someone scan this QR to collect a copy of your ${cards.find(c=>c.id===state.personal).name} card.</p><div class="qr">${qr.createSvgTag({scalable:true})}</div><p class="small-note">Sharing code: <b>${code}</b><br>Both people keep their cards. A copy earns points only if it’s new.</p><button class="primary" id="copy">Copy card link ↗</button><p class="small-note">Hosted access rules still apply. Demo codes work within this prototype.</p>`);$('#copy').onclick=async()=>{try{await navigator.clipboard.writeText(url.href);toast('Card link copied');}catch{const input=document.createElement('input');input.value=url.href;$('#modal-body').append(input);input.select();toast('Select and copy the link below.');}};}
async function camera(){if(!('BarcodeDetector' in window)){ $('#scan-error').textContent='QR camera scanning isn’t supported in this browser. Paste a link or try a demo code.';return;}try{const detector=new BarcodeDetector({formats:['qr_code']});stream=await navigator.mediaDevices.getUserMedia({video:{facingMode:'environment'}});if(screen!=='scan'||modal.open){stopCamera();return;}$('#scanner').innerHTML='<video autoplay muted playsinline></video><button class="secondary" id="stop-camera">Stop camera</button>';const video=$('#scanner video');video.srcObject=stream;await video.play();$('#stop-camera').onclick=()=>{stopCamera();render();};const detect=async()=>{if(!stream)return;try{const codes=await detector.detect(video);if(codes.length){stopCamera();render();openCode(codes[0].rawValue);return;}}catch{}scanTimer=setTimeout(detect,300);};detect();}catch{stopCamera();$('#scan-error').textContent='Camera unavailable or permission declined. Paste a link or use a demo code.';}}
document.querySelectorAll('[data-nav]').forEach(b=>b.onclick=()=>nav(b.dataset.nav));$('.brand').onclick=e=>{e.preventDefault();nav('home');};$('.close').onclick=()=>modal.close();modal.addEventListener('close',stopCamera);$('#reset').onclick=()=>{openModal('<h2>Start a fresh journey?</h2><p>This clears your cards, points and personal memories from this browser.</p><div class="actions"><button class="primary" id="confirm-reset">Reset my deck</button><button class="secondary" id="cancel-reset">Keep my cards</button></div>');$('#cancel-reset').onclick=()=>modal.close();$('#confirm-reset').onclick=()=>{state=blank();save();modal.close();history.replaceState(null,'',location.pathname);nav('home');toast('Your deck is ready for a fresh start.');};};
function readHash(){const code=new URLSearchParams(location.hash.slice(1)).get('card');if(code){nav('scan');openCode(code);}}window.addEventListener('hashchange',readHash);window.addEventListener('pagehide',()=>{stopCamera();disposeScene();});render();readHash();if(!storage)toast('Storage unavailable. Progress is kept for this session.');
